PYTHON_WORKLOAD = """\
import math

def axpy(a, x, y):
    for i in range(len(x)):
        y[i] = a * x[i] + y[i]
    return y

def wave(n):
    return [math.sin(i * 0.001) for i in range(n)]

def main():
    n = 200_000
    x = wave(n)
    y = [0.0] * n
    for _ in range(60):
        axpy(2.0, x, y)
    print(sum(y[:3]))

main()
"""
